function formatDateIndonesian(dateString) {
  if (!dateString) return "-";
  try {
    const d2 = new Date(dateString);
    if (isNaN(d2.getTime())) return dateString;
    const months = [
      "JANUARI",
      "FEBRUARI",
      "MARET",
      "APRIL",
      "MEI",
      "JUNI",
      "JULI",
      "AGUSTUS",
      "SEPTEMBER",
      "OKTOBER",
      "NOVEMBER",
      "DESEMBER"
    ];
    return `${d2.getDate()} ${months[d2.getMonth()]} ${d2.getFullYear()}`;
  } catch {
    return dateString;
  }
}
