function generateReportPDF(title, data, columns) {
  const doc = new import_jspdf.jsPDF({
    orientation: "landscape",
    unit: "mm",
    format: "a4"
  });
  doc.setFillColor(15, 118, 110);
  doc.rect(0, 0, 297, 24, "F");
  doc.setTextColor(255, 255, 255);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(14);
  doc.text("SMP AL-HADIID CILEUNGSI - LAPORAN OFFICIAL SPMB ONLINE", 148.5, 10, { align: "center" });
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
  doc.text(title.toUpperCase(), 148.5, 17, { align: "center" });
  let y2 = 32;
  doc.setTextColor(15, 23, 42);
  doc.setFontSize(9);
  doc.setFont("helvetica", "bold");
  const colWidth = 270 / columns.length;
  columns.forEach((col, idx) => {
    doc.setFillColor(226, 232, 240);
    doc.rect(14 + idx * colWidth, y2, colWidth, 8, "F");
    doc.text(col, 16 + idx * colWidth, y2 + 5.5);
  });
  y2 += 9;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  data.forEach((row, rowIndex) => {
    if (y2 > 180) {
      doc.addPage();
      y2 = 20;
    }
    if (rowIndex % 2 === 1) {
      doc.setFillColor(248, 250, 252);
      doc.rect(14, y2 - 1, 270, 7, "F");
    }
    columns.forEach((col, colIdx) => {
      const val = String(row[col] || "-");
      doc.text(val.substring(0, 28), 16 + colIdx * colWidth, y2 + 4);
    });
    y2 += 7;
  });
  doc.save(`Laporan_SPMB_${title.replace(/\s+/g, "_")}.pdf`);
}

